#include "llama-grammar.h"
#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
#include <sstream>
static std::string read(const char *p){std::ifstream f(p);std::stringstream s;s<<f.rdbuf();return s.str();}
bool accepts(const std::string &rules,const std::string &text){
 auto *grammar=llama_grammar_init_impl(nullptr,rules.c_str(),"root",false,nullptr,0,nullptr,0);
 if(!grammar)throw std::runtime_error("grammar rejected by pinned parser");
 for(unsigned char c:text){if(llama_grammar_get_stacks(grammar).empty()){llama_grammar_free_impl(grammar);return false;}llama_grammar_accept(grammar,c);}
 bool complete=false;for(const auto &stack:llama_grammar_get_stacks(grammar))if(stack.empty())complete=true;
 llama_grammar_free_impl(grammar);return complete;
}
int main(int argc,char **argv){
 if(argc!=3)return 2;std::string grammar=read(argv[1]);auto cases=nlohmann::json::parse(read(argv[2]));
 int failed=0;for(const auto &item:cases){bool got=accepts(grammar,item["input"]);bool expected=item["accepted"];std::cout<<item["name"]<<": "<<(got==expected?"PASS":"FAIL")<<"\n";if(got!=expected)failed++;}
 return failed?1:0;
}
